const checkBank = {};
Object.keys(taskBank).forEach(k=>{
  checkBank[k]=taskBank[k].filter(t=>t.type==='single'||t.type==='case'||t.type==='multi').map((t,i)=>({
    id:'c'+k+'-'+i,type:t.type==='case'?'single':t.type,prompt:t.prompt,options:t.options,answer:t.answer,why:t.why,refs:t.refs
  }));
});

Object.keys(caseBank).forEach(k=>{
  (caseBank[k]||[]).forEach((c,i)=>{
    checkBank[k].push({id:'case-'+k+'-'+i,type:'single',prompt:c.question,options:c.options,answer:c.answer,why:c.why,refs:c.refs});
  });
});

