function setCarousel(index,animate=true){
  const slides=[...document.querySelectorAll(".chapterSlide")],viewport=document.getElementById("carouselViewport");
  if(!slides.length||!viewport)return;
  carouselIndex=Math.max(0,Math.min(index,slides.length-1));
  slides.forEach((x,i)=>x.classList.toggle("active",i===carouselIndex));
  document.querySelectorAll(".carouselDot").forEach((x,i)=>x.classList.toggle("active",i===carouselIndex));
  document.getElementById("carouselPrev").disabled=carouselIndex===0;
  document.getElementById("carouselNext").disabled=carouselIndex===slides.length-1;
  const slide=slides[carouselIndex];
  const left=slide.offsetLeft-(viewport.clientWidth-slide.clientWidth)/2;
  viewport.scrollTo({left,behavior:animate?"smooth":"auto"})
}
function bindCarousel(){
  const viewport=document.getElementById("carouselViewport");if(!viewport)return;
  document.getElementById("carouselPrev").onclick=()=>setCarousel(carouselIndex-1);
  document.getElementById("carouselNext").onclick=()=>setCarousel(carouselIndex+1);

  const isInteractive=el=>!!el?.closest?.("button,a,input,textarea,select,label,[role='button']");

  viewport.onpointerdown=e=>{
    if(isInteractive(e.target)){carouselDrag=null;return}
    carouselDrag={x:e.clientX,left:viewport.scrollLeft,pointerId:e.pointerId,moved:false};
    viewport.setPointerCapture?.(e.pointerId)
  };
  viewport.onpointermove=e=>{
    if(!carouselDrag)return;
    const dx=e.clientX-carouselDrag.x;
    if(Math.abs(dx)>6)carouselDrag.moved=true;
    viewport.scrollLeft=carouselDrag.left-dx
  };
  viewport.onpointerup=e=>{
    if(!carouselDrag)return;
    const dx=e.clientX-carouselDrag.x,moved=carouselDrag.moved;
    try{viewport.releasePointerCapture?.(carouselDrag.pointerId)}catch(_){}
    carouselDrag=null;
    if(moved&&Math.abs(dx)>45)setCarousel(carouselIndex+(dx<0?1:-1));
    else setCarousel(carouselIndex)
  };
  viewport.onpointercancel=()=>{
    if(carouselDrag){try{viewport.releasePointerCapture?.(carouselDrag.pointerId)}catch(_){}}
    carouselDrag=null;setCarousel(carouselIndex)
  };

  viewport.tabIndex=0;
  viewport.onkeydown=e=>{
    if(e.key==="ArrowLeft"){e.preventDefault();setCarousel(carouselIndex-1)}
    if(e.key==="ArrowRight"){e.preventDefault();setCarousel(carouselIndex+1)}
  };

  if(carouselResizeObserver)carouselResizeObserver.disconnect();
  if("ResizeObserver" in window){
    carouselResizeObserver=new ResizeObserver(()=>requestAnimationFrame(()=>setCarousel(carouselIndex,false)));
    carouselResizeObserver.observe(viewport)
  }
}
