let schemeSession={selected:null,matched:0,total:0,kind:null};

function schemeShuffle(items){
  return items.map((x,i)=>({x,r:(i+1)*7919%9973})).sort((a,b)=>a.r-b.r).map(v=>v.x);
}
function schemeChipHTML(chip){
  return '<button class="schemeChip rippleHost" draggable="true" data-chip="'+chip.id+'"><span class="schemeChipIcon">'+chip.icon+'</span><span>'+capUi(chip.text)+'</span></button>';
}
function schemeTargetHTML(target,kind){
  const hint=kind==="flow"?"Перетащите сюда смысл элемента":"Перетащите сюда подходящие элементы";
  return '<div class="schemeTarget '+(kind==="flow"?"flowTarget":"laneTarget")+'" data-target="'+target.id+'">'+
    '<div class="schemeTargetHalo"></div><div class="schemeTargetIcon">'+target.icon+'</div>'+
    '<div class="schemeTargetTitle">'+capUi(target.title)+'</div>'+
    '<div class="schemeTargetHint">'+hint+'</div><div class="schemeTargetDrops"></div></div>';
}
function schemeBuildModel(){
  const d=moduleInfo[currentModule].diagram;
  if(d.kind==="flow"){
    const targets=d.nodes.map((n,i)=>({id:"t"+i,icon:n[0],title:n[1],order:i}));
    const chips=d.nodes.map((n,i)=>({id:"c"+i,icon:n[0],text:n[2],target:"t"+i}));
    return {kind:"flow",targets,chips,total:chips.length,title:d.title,caption:d.caption};
  }
  const laneIcons=["◆","◇","○","□","△","◎"];
  const targets=d.lanes.map((l,i)=>({id:"t"+i,icon:laneIcons[i%laneIcons.length],title:l[0],order:i}));
  const chips=[];
  d.lanes.forEach((l,i)=>(l[1]||[]).forEach((item,j)=>chips.push({id:"c"+i+"_"+j,icon:laneIcons[i%laneIcons.length],text:item,target:"t"+i})));
  return {kind:"lanes",targets,chips,total:chips.length,title:d.title,caption:d.caption};
}
function renderScheme(){
  const model=schemeBuildModel(),panel=document.getElementById("panel");
  schemeSession={selected:null,matched:0,total:model.total,kind:model.kind};
  const targets=model.targets.map(t=>schemeTargetHTML(t,model.kind)).join("");
  const chips=schemeShuffle(model.chips).map(schemeChipHTML).join("");
  panel.innerHTML='<div class="schemeLab">'+
    '<div class="schemeLabHead"><div><div class="eyebrow">Интерактивная схема</div><h3>'+capUi(model.title)+'</h3><p>'+capUi(model.caption)+'</p></div>'+
    '<div class="schemeScore"><b id="schemeMatched">0</b><span>/ '+model.total+' собрано</span></div></div>'+
    '<div class="schemeWorkspace"><section class="schemeCanvas '+model.kind+'" id="schemeCanvas"><div class="schemeConnectors"></div>'+targets+'</section>'+
    '<aside class="schemeToolbox"><div><div class="schemeToolboxTitle">Сопоставьте элементы</div><p>Перетаскивайте карточки на схему. На телефоне: сначала нажмите карточку, затем нужную область.</p></div>'+
    '<div class="schemeChipPool" id="schemeChipPool">'+chips+'</div>'+
    '<div class="schemeToolboxActions"><button class="btn ghost rippleHost" id="schemeHintBtn">Подсказка</button><button class="btn ghost rippleHost" id="schemeResetBtn">Сбросить</button><button class="btn primary rippleHost" id="schemeCasesBtn">К кейсам →</button></div></aside></div>'+
    '<div class="schemeFeedback" id="schemeFeedback"><b>Соберите схему.</b> Правильный элемент «прилипнет» к своей зоне, связи будут подсвечиваться.</div></div>';
  bindSchemeInteractions(model);
  bindRipple()
}
function bindSchemeInteractions(model){
  const chipMap=Object.fromEntries(model.chips.map(x=>[x.id,x]));
  const targetMap=Object.fromEntries(model.targets.map(x=>[x.id,x]));
  const pool=document.getElementById("schemeChipPool"),feedback=document.getElementById("schemeFeedback");
  const targets=[...document.querySelectorAll(".schemeTarget")],chips=[...document.querySelectorAll(".schemeChip")];

  function selectChip(el){
    chips.forEach(x=>x.classList.remove("selected"));
    if(!el||el.classList.contains("placed")){schemeSession.selected=null;return}
    el.classList.add("selected");schemeSession.selected=el.dataset.chip;
  }
  function reject(target,chipEl){
    errorSound();target.classList.add("wrongDrop");chipEl?.classList.add("shake");
    feedback.innerHTML='<b>Не совпало.</b> Посмотрите на функцию или смысл элемента и попробуйте другую область.';
    setTimeout(()=>{target.classList.remove("wrongDrop");chipEl?.classList.remove("shake")},420)
  }
  function accept(target,chipEl,chip){
    if(chipEl.classList.contains("placed"))return;
    successSound();
    const drops=target.querySelector(".schemeTargetDrops");
    const placed=document.createElement("div");placed.className="placedSchemeChip";
    placed.innerHTML='<span>'+chip.icon+'</span><b>'+capUi(chip.text)+'</b>';
    drops.appendChild(placed);
    chipEl.classList.add("placed");chipEl.setAttribute("aria-disabled","true");
    target.classList.add("filled","snapPulse");
    setTimeout(()=>target.classList.remove("snapPulse"),360);
    schemeSession.matched++;
    document.getElementById("schemeMatched").textContent=schemeSession.matched;
    selectChip(null);
    feedback.innerHTML='<b>Верно.</b> '+capUi(chip.text)+' связано с «'+capUi(targetMap[target.dataset.target].title)+'».';
    updateSchemeConnectors(model);
    if(schemeSession.matched===schemeSession.total){
      document.getElementById("schemeCanvas").classList.add("complete");
      feedback.innerHTML='<b>Схема собрана.</b> Теперь связи видны целиком — можно перейти к жизненным кейсам.';
      confetti(document.getElementById("schemeCanvas"));xpPop(60,document.getElementById("schemeCanvas"));
    }
  }
  function place(chipId,targetEl){
    const chip=chipMap[chipId],chipEl=document.querySelector('.schemeChip[data-chip="'+chipId+'"]');
    if(!chip||!chipEl||chipEl.classList.contains("placed"))return;
    if(chip.target===targetEl.dataset.target)accept(targetEl,chipEl,chip);else reject(targetEl,chipEl)
  }

  chips.forEach(chip=>{
    chip.addEventListener("click",()=>selectChip(chip));
    chip.addEventListener("dragstart",e=>{
      if(chip.classList.contains("placed")){e.preventDefault();return}
      e.dataTransfer.setData("text/plain",chip.dataset.chip);e.dataTransfer.effectAllowed="move";
      chip.classList.add("dragging")
    });
    chip.addEventListener("dragend",()=>chip.classList.remove("dragging"));
  });
  targets.forEach(target=>{
    target.addEventListener("click",()=>{if(schemeSession.selected)place(schemeSession.selected,target)});
    target.addEventListener("dragover",e=>{e.preventDefault();target.classList.add("over")});
    target.addEventListener("dragleave",()=>target.classList.remove("over"));
    target.addEventListener("drop",e=>{
      e.preventDefault();target.classList.remove("over");
      place(e.dataTransfer.getData("text/plain"),target)
    });
  });

  document.getElementById("schemeHintBtn").onclick=()=>{
    const available=model.chips.find(c=>!document.querySelector('.schemeChip[data-chip="'+c.id+'"]').classList.contains("placed"));
    if(!available)return;
    const chipEl=document.querySelector('.schemeChip[data-chip="'+available.id+'"]');
    const targetEl=document.querySelector('.schemeTarget[data-target="'+available.target+'"]');
    selectChip(chipEl);targetEl.classList.add("hintGlow");feedback.innerHTML='<b>Подсказка:</b> подсвечена область, куда относится выбранный элемент.';
    setTimeout(()=>targetEl.classList.remove("hintGlow"),1400)
  };
  document.getElementById("schemeResetBtn").onclick=()=>renderScheme();
  document.getElementById("schemeCasesBtn").onclick=()=>switchTab("cases");
}
function updateSchemeConnectors(model){
  if(model.kind!=="flow")return;
  const targets=[...document.querySelectorAll(".schemeTarget")];
  targets.forEach((t,i)=>{
    if(i<targets.length-1 && t.classList.contains("filled") && targets[i+1].classList.contains("filled")){
      t.classList.add("linkRight")
    }
  })
}
function renderPractice(){
  const rem=remainingTasks(),panel=document.getElementById('panel');
  if(!currentTask&&rem.length)currentTask=rem[0];
  if(!currentTask){
    panel.innerHTML='<div class="finish"><div><div class="score">✓</div><h3>Все уникальные задания пройдены</h3><p>Автоматических повторов нет. Второй круг запускается только вручную.</p><div class="row"><button class="btn ghost" onclick="restartPractice()">Начать второй круг</button><button class="btn primary" onclick="switchTab(\'coach\')">К ИИ‑тренеру →</button></div></div></div>';return
  }
  const total=taskBank[currentModule].length,done=state.doneTasks[currentModule]?.length||0;
  panel.innerHTML='<div class="practice"><div class="taskArea"><div class="taskMeta"><span class="tag">'+currentTask.label+'</span><span class="count">'+(done+1)+' / '+total+'</span></div>'+
    '<div class="taskPrompt">'+currentTask.prompt+'</div><div class="taskSub">Номер нормы вспоминать не нужно: после решения вы увидите правовое основание.</div><div class="answerZone" id="answerZone"></div>'+
    '<div class="feedback" id="feedback">Решите задачу. Ошибка не закрывает попытку.</div></div>'+
    '<aside class="taskSide"><div><div class="eyebrow">Без повторов</div><h3>Уникальная очередь</h3><p>Каждое задание этого раздела появляется один раз.</p></div><div class="doneBox"><b>'+done+' / '+total+'</b>заданий завершено</div>'+
    '<div class="taskDots">'+taskBank[currentModule].map(t=>'<div class="taskDot '+((state.doneTasks[currentModule]||[]).includes(t.id)?'done ':'')+(t.id===currentTask.id?'current':'')+'"></div>').join('')+'</div><button class="btn ghost" onclick="switchTab(\'scheme\')">Посмотреть схему</button></aside></div>';
  renderTaskInput(currentTask)
}
function restartPractice(){state.doneTasks[currentModule]=[];currentTask=null;save();updateProgress();renderPractice()}
function switchTab(tab){activateCourseTab(tab)}
function renderTaskInput(t){
  const z=document.getElementById('answerZone');z.innerHTML='';
  if(t.type==='single'||t.type==='case'||t.type==='multi'){
    const a=document.createElement('div');a.className='answers';
    t.options.forEach((o,i)=>{const text=Array.isArray(o)?o[0]:o,b=document.createElement('button');b.className='ans';b.dataset.i=i;b.innerHTML='<span class="letter">'+('ABCD'[i]||'•')+'</span><span>'+text+'</span>';b.onclick=()=>t.type==='multi'?b.classList.toggle('selected'):answerSingle(i,b);a.appendChild(b)});
    if(t.type==='multi'){const c=document.createElement('button');c.className='btn primary check';c.textContent='Проверить выбранные';c.onclick=answerMulti;a.appendChild(c)}
    z.appendChild(a);return
  }
  if(t.type==='match'){
    const g=document.createElement('div');g.className='matchGrid';const rights=t.pairs.map(p=>p[1]);
    t.pairs.forEach((p,i)=>{const r=document.createElement('div');r.className='matchRow';r.innerHTML='<div class="matchLeft">'+p[0]+'</div><div class="matchArrow">→</div><select class="matchSelect" data-i="'+i+'"><option value="">Выберите…</option>'+rights.map(x=>'<option value="'+encodeURIComponent(x)+'">'+x+'</option>').join('')+'</select>';g.appendChild(r)});
    const c=document.createElement('button');c.className='btn primary check';c.textContent='Проверить сопоставление';c.onclick=answerMatch;g.appendChild(c);z.appendChild(g);return
  }
  if(t.type==='order'){
    const order=t.steps.map((x,i)=>({id:String(i),text:x})).sort(()=>Math.random()-.5);if(order.every((x,i)=>x.id===String(i)))order.reverse();
    const g=document.createElement('div');g.className='orderList';g.id='orderList';
    order.forEach(x=>{const r=document.createElement('div');r.className='orderItem';r.dataset.id=x.id;r.innerHTML='<div class="orderNum">•</div><span>'+x.text+'</span><div><button class="move" onclick="moveOrder(\''+x.id+'\',-1)">↑</button> <button class="move" onclick="moveOrder(\''+x.id+'\',1)">↓</button></div>';g.appendChild(r)});
    const c=document.createElement('button');c.className='btn primary check';c.textContent='Проверить порядок';c.onclick=answerOrder;g.appendChild(c);z.appendChild(g);renumberOrder();return
  }
  if(t.type==='classify'){
    const g=document.createElement('div');g.className='matchGrid';
    t.items.forEach((it,i)=>{const r=document.createElement('div');r.className='matchRow';r.innerHTML='<div class="matchLeft">'+it[0]+'</div><div class="matchArrow">→</div><select class="matchSelect" data-i="'+i+'"><option value="">Выберите…</option>'+t.groups.map(gr=>'<option value="'+gr[0]+'">'+gr[1]+'</option>').join('')+'</select>';g.appendChild(r)});
    const c=document.createElement('button');c.className='btn primary check';c.textContent='Проверить распределение';c.onclick=answerClassify;g.appendChild(c);z.appendChild(g)
  }
}
function fail(msg,el){errorSound();if(el&&el.classList){el.classList.add('wrong','shake');setTimeout(()=>el.classList.remove('shake'),350)}document.getElementById('feedback').innerHTML='<b>Не получилось.</b> '+msg+' Попробуйте ещё раз — правильный вариант не раскрывается автоматически.';if(el&&el.classList)setTimeout(()=>el.classList.remove('wrong'),500)}
function succeed(el){
  successSound();if(el&&el.classList)el.classList.add('correct','glowSuccess');confetti(el);xpPop(35,el);
  document.getElementById('feedback').innerHTML='<b>Верно.</b> '+currentTask.why+' <span class="refs">Основание: '+currentTask.refs+'</span>';
  if(!state.doneTasks[currentModule])state.doneTasks[currentModule]=[];
  if(!state.doneTasks[currentModule].includes(currentTask.id))state.doneTasks[currentModule].push(currentTask.id);
  save();updateProgress();const solvedModule=currentModule;setTimeout(()=>{if(currentModule===solvedModule&&currentTab==="practice"){currentTask=null;renderPractice()}},1100)
}
function answerSingle(i,b){i===currentTask.answer?succeed(b):fail('Выбранный вывод не следует из конституционной логики ситуации.',b)}
function answerMulti(){
  const got=[...document.querySelectorAll('.ans.selected')].map(x=>+x.dataset.i).sort((a,b)=>a-b);
  const need=currentTask.options.map((o,i)=>Array.isArray(o)&&o[1]?i:null).filter(x=>x!==null);
  got.length===need.length&&got.every((x,i)=>x===need[i])?succeed(document.querySelector('.check')):fail('Набор неполный или содержит лишний вариант.',document.querySelector('.check'))
}
function answerMatch(){
  const s=[...document.querySelectorAll('.matchSelect')];let ok=true;
  s.forEach((x,i)=>{const v=x.value?decodeURIComponent(x.value):'',good=v===currentTask.pairs[i][1];x.classList.toggle('bad',!good);if(!good)ok=false});
  ok?succeed():fail('Есть неверные соответствия.',null)
}
function moveOrder(id,d){
  const g=document.getElementById('orderList'),rows=[...g.querySelectorAll('.orderItem')],el=rows.find(x=>x.dataset.id===id),i=rows.indexOf(el),j=i+d;
  if(j<0||j>=rows.length)return;if(d<0)g.insertBefore(el,rows[j]);else g.insertBefore(rows[j],el);renumberOrder()
}
function renumberOrder(){document.querySelectorAll('#orderList .orderItem').forEach((x,i)=>x.querySelector('.orderNum').textContent=i+1)}
function answerOrder(){
  const got=[...document.querySelectorAll('#orderList .orderItem')].map(x=>x.dataset.id),ok=got.every((x,i)=>x===String(i));
  document.querySelectorAll('#orderList .orderItem').forEach((x,i)=>x.classList.toggle('bad',got[i]!==String(i)));
  ok?succeed():fail('Этапы стоят не в той последовательности.',null)
}
function answerClassify(){
  const s=[...document.querySelectorAll('.matchSelect')];let ok=true;
  s.forEach((x,i)=>{const good=x.value===currentTask.items[i][1];x.classList.toggle('bad',!good);if(!good)ok=false});
  ok?succeed():fail('Часть позиций попала не в ту категорию.',null)
}

